///
/// Example:
///
/// <code>
/// type A = {
/// 	discriminant: 'A';
/// 	foo: {
/// 		bar: string;
/// 	};
/// };
///
/// type B = {
/// 	discriminant: 'B';
/// 	foo: {
/// 		baz: string;
/// 	};
