/// }
/// </code>
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {DistributedPick} from 'type-fest';
///
/// type A = {
/// discriminant: 'A';
/// foo: {
/// bar: string;
/// };
/// extraneous: boolean;
/// };
///
/// type B = {
/// discriminant: 'B';
/// foo: {
/// baz: string;
/// };
/// extraneous: boolean;
/// };
///
/// // Notice that `foo.bar` exists in `A` but not in `B`.
///
/// type Union = A | B;
///
/// type PickedUnion = DistributedPick&lt;Union, 'discriminant' | 'foo'&gt;;
///
/// declare const pickedUnion: PickedUnion;
///
