/// // @ts-expect-error
/// const bazValue = pickedUnion.foo.baz;
/// // Error: `bar` is not a property of `{discriminant: 'A'; a: string}`.
/// }
/// </code>
/// </remarks>
/// <remarks>@category Object</remarks>
[<Erase>]
type DistributedPick<'ObjectType, 'KeyType> = private DistributedPick__ of obj

