///
/// declare const objectMerge: ObjectMerge&lt;typeof left, typeof right&gt;;
/// //=&gt; {[x: string]: string | number; a: string | number}
///
/// // @ts-expect-error
/// objectMerge.a.toUpperCase(); // Correctly errors at compile time.
/// </code>
///
/// Can be used to merge generic type arguments.
///
/// In the following example, object spread without <c>ObjectMerge</c> produces an intersection type that is not particularly usable, whereas <c>ObjectMerge</c> produces a correctly merged and usable result.
/// </remarks>
/// <remarks>
/// @example
/// <code lang="ts">
/// import type {ObjectMerge} from 'type-fest';
///
/// function withoutObjectMerge&lt;T extends object, U extends object&gt;(left: T, right: U) {
/// return {...left, ...right};
/// }
///
/// const result1 = withoutObjectMerge({a: 1}, {a: 'one'});
/// //=&gt; {a: number} &amp; {a: string}
///
/// const {a} = result1;
/// //=&gt; never
///
/// function withObjectMerge&lt;T extends object, U extends object&gt;(left: T, right: U) {
/// return {...left, ...right} as unknown as ObjectMerge&lt;T, U&gt;;
/// }
///
/// const result2 = withObjectMerge({b: 1}, {b: 'one'});
/// //=&gt; {b: string}
///
/// const {b} = result2;
/// //=&gt; string
/// </code>
///
/// Note: If you want a simple merge where properties from the second object always override properties from the first object without considering runtime implications, refer to the {@link Merge} type.
/// </remarks>
/// <remarks>@see {@link Merge}</remarks>
/// <remarks>@category Object</remarks>
[<Erase>]
type ObjectMerge<'First, 'Second> = private ObjectMerge__ of obj

/// <summary>
/// Omit properties from a deeply-nested object.
///
/// It supports recursing into arrays.
///
/// It supports removing specific items from an array, replacing each removed item with unknown at the specified index.
///
/// Use-case: Remove unneeded parts of complex objects.
///
/// Use [<c>Omit&lt;T&gt;</c>](https://www.typescriptlang.org/docs/handbook/utility-types.html#omittype-keys) if you only need one level deep.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {OmitDeep} from 'type-fest';
///
/// type Info = {
/// userInfo: {
/// name: string;
/// uselessInfo: {
/// foo: string;
/// };
/// };
/// };
///
/// type UsefulInfo = OmitDeep&lt;Info, 'userInfo.uselessInfo'&gt;;
/// //=&gt; {userInfo: {name: string}}
///
/// // Supports removing multiple paths
/// type Info1 = {
/// userInfo: {
/// name: string;
/// uselessField: string;
/// uselessInfo: {
/// foo: string;
/// };
/// };
/// };
///
/// type UsefulInfo1 = OmitDeep&lt;Info1, 'userInfo.uselessInfo' | 'userInfo.uselessField'&gt;;
/// //=&gt; {userInfo: {name: string}}
///
/// // Supports array
/// type A = OmitDeep&lt;[1, 'foo', 2], '1'&gt;;
/// //=&gt; [1, unknown, 2]
///
/// // Supports recursing into array
///
/// type Info2 = {
/// address: [
/// {
/// street: string;
/// },
/// {
/// street2: string;
/// foo: string;
/// },
/// ];
/// };
///
/// type AddressInfo = OmitDeep&lt;Info2, 'address.1.foo'&gt;;
/// //=&gt; {address: [{street: string}, {street2: string}]}
/// </code>
/// </remarks>
/// <remarks>@category Object</remarks>
/// <remarks>@category Array</remarks>
[<Erase>]
type OmitDeep<'T, 'PathUnion> = private OmitDeep__ of obj

/// <summary>
/// Omit any index signatures from the given object type, leaving only explicitly defined properties.
///
/// This is the counterpart of <c>PickIndexSignature</c>.
///
/// Use-cases:
/// - Remove overly permissive signatures from third-party types.
///
/// This type was taken from this [StackOverflow answer](https://stackoverflow.com/a/68261113/420747).
///
/// It relies on the fact that an empty object (<c>{}</c>) is assignable to an object with just an index signature, like <c>Record&lt;string, unknown&gt;</c>, but not to an object with explicitly defined keys, like <c>Record&lt;'foo' | 'bar', unknown&gt;</c>.
///
/// (The actual value type, <c>unknown</c>, is irrelevant and could be any type. Only the key type matters.)
///
/// <code>
/// const indexed: Record&lt;string, unknown&gt; = {}; // Allowed
///
/// // @ts-expect-error
/// const keyed: Record&lt;'foo', unknown&gt; = {}; // Error
/// // TS2739: Type '{}' is missing the following properties from type 'Record&lt;"foo" | "bar", unknown&gt;': foo, bar
/// </code>
///
/// Instead of causing a type error like the above, you can also use a [conditional type](https://www.typescriptlang.org/docs/handbook/2/conditional-types.html) to test whether a type is assignable to another:
///
/// <code>
/// type Indexed = {} extends Record&lt;string, unknown&gt;
/// 	? '✅ `{}` is assignable to `Record&lt;string, unknown&gt;`'
/// 	: '❌ `{}` is NOT assignable to `Record&lt;string, unknown&gt;`';
///
/// type IndexedResult = Indexed;
/// //=&gt; '✅ `{}` is assignable to `Record&lt;string, unknown&gt;`'
///
/// type Keyed = {} extends Record&lt;'foo' | 'bar', unknown&gt;
/// 	? '✅ `{}` is assignable to `Record&lt;\'foo\' | \'bar\', unknown&gt;`'
/// 	: '❌ `{}` is NOT assignable to `Record&lt;\'foo\' | \'bar\', unknown&gt;`';
///
/// type KeyedResult = Keyed;
/// //=&gt; '❌ `{}` is NOT assignable to `Record&lt;\'foo\' | \'bar\', unknown&gt;`'
/// </code>
///
/// Using a [mapped type](https://www.typescriptlang.org/docs/handbook/2/mapped-types.html#further-exploration), you can then check for each <c>KeyType</c> of <c>ObjectType</c>...
///
/// <code>
/// type OmitIndexSignature&lt;ObjectType&gt; = {
/// 	[KeyType in keyof ObjectType // Map each key of `ObjectType`...
/// 	]: ObjectType[KeyType]; // ...to its original value, i.e. `OmitIndexSignature&lt;Foo&gt; == Foo`.
/// };
/// </code>
///
/// ...whether an empty object (<c>{}</c>) would be assignable to an object with that <c>KeyType</c> (<c>Record&lt;KeyType, unknown&gt;</c>)...
///
/// <code>
/// type OmitIndexSignature&lt;ObjectType&gt; = {
/// 	[KeyType in keyof ObjectType
/// 	// Is `{}` assignable to `Record&lt;KeyType, unknown&gt;`?
/// 	as {} extends Record&lt;KeyType, unknown&gt;
/// 		? never // ✅ `{}` is assignable to `Record&lt;KeyType, unknown&gt;`
/// 		: KeyType // ❌ `{}` is NOT assignable to `Record&lt;KeyType, unknown&gt;`
/// 	]: ObjectType[KeyType];
/// };
/// </code>
///
/// If <c>{}</c> is assignable, it means that <c>KeyType</c> is an index signature and we want to remove it. If it is not assignable, <c>KeyType</c> is a "real" key and we want to keep it.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {OmitIndexSignature} from 'type-fest';
///
/// type Example = {
/// // These index signatures will be removed.
/// [x: string]: any;
/// [x: number]: any;
/// [x: symbol]: any;
/// [x: `head-${string}`]: string;
/// [x: `${string}-tail`]: string;
/// [x: `head-${string}-tail`]: string;
/// [x: `${bigint}`]: string;
/// [x: `embedded-${number}`]: string;
///
/// // These explicitly defined keys will remain.
/// foo: 'bar';
/// qux?: 'baz';
/// };
///
/// type ExampleWithoutIndexSignatures = OmitIndexSignature&lt;Example&gt;;
/// //=&gt; {foo: 'bar'; qux?: 'baz'}
/// </code>
/// </remarks>
/// <remarks>@see {@link PickIndexSignature}</remarks>
/// <remarks>@category Object</remarks>
[<Erase>]
type OmitIndexSignature<'ObjectType> = private OmitIndexSignature__ of obj

/// <summary>
/// Extract all optional keys from the given type.
///
/// This is useful when you want to create a new type that contains different type values for the optional keys only.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {OptionalKeysOf, Except} from 'type-fest';
///
/// type User = {
/// name: string;
/// surname: string;
///
/// luckyNumber?: number;
/// };
///
/// const REMOVE_FIELD = Symbol('remove field symbol');
/// type UpdateOperation&lt;Entity extends object&gt; = Except&lt;Partial&lt;Entity&gt;, OptionalKeysOf&lt;Entity&gt;&gt; &amp; {
/// [Key in OptionalKeysOf&lt;Entity&gt;]?: Entity[Key] | typeof REMOVE_FIELD;
/// };
///
/// const update1: UpdateOperation&lt;User&gt; = {
/// name: 'Alice',
/// };
///
/// const update2: UpdateOperation&lt;User&gt; = {
/// name: 'Bob',
/// luckyNumber: REMOVE_FIELD,
/// };
/// </code>
/// </remarks>
/// <remarks>@category Utilities</remarks>
[<Erase>]
type OptionalKeysOf<'Type> = private OptionalKeysOf__ of obj

/// <summary>
/// Create a type that represents either the value or <c>undefined</c>, while stripping <c>null</c> from the type.
///
/// Use-cases:
/// - Enforcing the practice of using <c>undefined</c> instead of <c>null</c> as the "absence of value" marker.
/// - Converting APIs that return <c>null</c> (DOM, JSON, legacy libraries) to use <c>undefined</c> consistently.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {Optional} from 'type-fest';
///
/// // Adds `undefined` to the type
/// type MaybeNumber = Optional&lt;number&gt;;
/// //=&gt; number | undefined
///
/// // Strips `null` from the type
/// type NullableString = Optional&lt;string | null&gt;;
/// //=&gt; string | undefined
///
/// type Config = {
/// name: string;
/// description: Optional&lt;string&gt;;
/// //=&gt; string | undefined
/// };
/// </code>
/// </remarks>
/// <remarks>@category Utilities</remarks>
[<Erase>]
type Optional<'Value> = private Optional__ of obj

/// <summary>
/// Returns a boolean for whether any of the given elements is <c>true</c>.
///
/// Use-cases:
/// - Check if at least one condition in a list of booleans is met.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {OrAll} from 'type-fest';
///
/// type FFT = OrAll&lt;[false, false, true]&gt;;
/// //=&gt; true
///
/// type FFF = OrAll&lt;[false, false, false]&gt;;
/// //=&gt; false
/// </code>
///
/// Note: When <c>boolean</c> is passed as an element, it is distributed into separate cases, and the final result is a union of those cases.
/// For example, <c>OrAll&lt;[false, boolean]&gt;</c> expands to <c>OrAll&lt;[false, true]&gt; | OrAll&lt;[false, false]&gt;</c>, which simplifies to <c>true | false</c> (i.e., <c>boolean</c>).
/// </remarks>
/// <remarks>
/// @example
/// <code>
/// import type {OrAll} from 'type-fest';
///
/// type A = OrAll&lt;[false, boolean]&gt;;
/// //=&gt; boolean
///
/// type B = OrAll&lt;[true, boolean]&gt;;
/// //=&gt; true
/// </code>
///
/// Note: If <c>never</c> is passed as an element, it is treated as <c>false</c> and the result is computed accordingly.
/// </remarks>
/// <remarks>
/// @example
/// <code>
/// import type {OrAll} from 'type-fest';
///
/// type A = OrAll&lt;[never, never, true]&gt;;
/// //=&gt; true
///
/// type B = OrAll&lt;[never, never, false]&gt;;
/// //=&gt; false
///
/// type C = OrAll&lt;[never, never, never]&gt;;
/// //=&gt; false
///
/// type D = OrAll&lt;[never, never, boolean]&gt;;
/// //=&gt; boolean
/// </code>
///
/// Note: If <c>any</c> is passed as an element, it is treated as <c>boolean</c> and the result is computed accordingly.
/// </remarks>
/// <remarks>
/// @example
/// <code>
/// import type {OrAll} from 'type-fest';
///
/// type A = OrAll&lt;[false, any]&gt;;
/// //=&gt; boolean
///
/// type B = OrAll&lt;[true, any]&gt;;
/// //=&gt; true
/// </code>
///
/// Note: <c>OrAll&lt;[]&gt;</c> evaluates to <c>false</c> because there are no <c>true</c> elements in an empty tuple. See [Wikipedia: Clause (logic) &gt; Empty clauses](https://en.wikipedia.org/wiki/Clause_(logic)#Empty_clauses:~:text=The%20truth%20evaluation%20of%20an%20empty%20disjunctive%20clause%20is%20always%20false.).
/// </remarks>
/// <remarks>@see {@link Or}</remarks>
/// <remarks>@see {@link AndAll}</remarks>
[<Erase>]
type OrAll<'T> = private OrAll__ of obj

/// <summary>
/// Returns a boolean for whether either of two given types is <c>true</c>.
///
/// Use-case: Constructing complex conditional types where at least one condition must be satisfied.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {Or} from 'type-fest';
///
/// type TT = Or&lt;true, true&gt;;
/// //=&gt; true
///
/// type TF = Or&lt;true, false&gt;;
/// //=&gt; true
///
/// type FT = Or&lt;false, true&gt;;
/// //=&gt; true
///
/// type FF = Or&lt;false, false&gt;;
/// //=&gt; false
/// </code>
///
/// Note: When <c>boolean</c> is passed as an argument, it is distributed into separate cases, and the final result is a union of those cases.
/// For example, <c>Or&lt;false, boolean&gt;</c> expands to <c>Or&lt;false, true&gt; | Or&lt;false, false&gt;</c>, which simplifies to <c>true | false</c> (i.e., <c>boolean</c>).
/// </remarks>
/// <remarks>
/// @example
/// <code>
/// import type {Or} from 'type-fest';
///
/// type A = Or&lt;false, boolean&gt;;
/// //=&gt; boolean
///
/// type B = Or&lt;boolean, false&gt;;
/// //=&gt; boolean
///
/// type C = Or&lt;true, boolean&gt;;
/// //=&gt; true
///
/// type D = Or&lt;boolean, true&gt;;
/// //=&gt; true
///
/// type E = Or&lt;boolean, boolean&gt;;
/// //=&gt; boolean
/// </code>
///
/// Note: If <c>never</c> is passed as an argument, it is treated as <c>false</c> and the result is computed accordingly.
/// </remarks>
/// <remarks>
/// @example
/// <code>
/// import type {Or} from 'type-fest';
///
/// type A = Or&lt;true, never&gt;;
/// //=&gt; true
///
/// type B = Or&lt;never, true&gt;;
/// //=&gt; true
///
/// type C = Or&lt;false, never&gt;;
/// //=&gt; false
///
/// type D = Or&lt;never, false&gt;;
/// //=&gt; false
///
/// type E = Or&lt;boolean, never&gt;;
/// //=&gt; boolean
///
/// type F = Or&lt;never, boolean&gt;;
/// //=&gt; boolean
///
/// type G = Or&lt;never, never&gt;;
/// //=&gt; false
/// </code>
/// </remarks>
/// <remarks>@see {@link OrAll}</remarks>
/// <remarks>@see {@link And}</remarks>
/// <remarks>@see {@link Xor}</remarks>
type Or = obj

/// <summary>
/// Override existing properties of the given type. Similar to <c>Merge</c>, but enforces that the original type has the properties you want to override.
///
/// This is useful when you want to override existing properties with a different type and make sure that these properties really exist in the original.
/// </summary>
/// <remarks>
/// @example
/// <code>
/// import type {OverrideProperties} from 'type-fest';
///
/// type Foo = {
/// a: string;
/// b: string;
/// };
///
/// type Bar = OverrideProperties&lt;Foo, {b: number}&gt;;
/// //=&gt; {a: string; b: number}
///
/// // @ts-expect-error
/// type Baz = OverrideProperties&lt;Foo, {c: number}&gt;;
/// // Error, type '{ c: number; }' does not satisfy the constraint '{ c: never; }'
///
/// // @ts-expect-error
/// type Fizz = OverrideProperties&lt;Foo, {b: number; c: number}&gt;;
/// // Error, type '{ b: number; c: number; }' does not satisfy the constraint '{ b: number; c: never; }'
/// </code>
/// </remarks>
/// <remarks>@category Object</remarks>
[<Erase>]
type OverrideProperties<'TOriginal, 'TOverride> = private OverrideProperties__ of obj

/// <summary>
/// Type for [npm's <c>package.json</c> file](https://docs.npmjs.com/creating-a-package-json-file). Also includes types for fields used by other popular projects, like TypeScript and Yarn.
/// </summary>
/// <remarks>@category File</remarks>
type PackageJson =
    inherit JsonObject
    /// <summary>
    /// Defines which package manager is expected to be used when working on the current project. It can set to any of the [supported package managers](https://nodejs.org/api/corepack.html#supported-package-managers), and will ensure that your teams use the exact same package manager versions without having to install anything else than Node.js.
    ///
    /// __This field is currently experimental and needs to be opted-in; check the [Corepack](https://nodejs.org/api/corepack.html) page for details about the procedure.__
    /// </summary>
    /// <remarks>
    /// @example
    /// <code lang="json">
    /// {
    /// 	"packageManager": "&lt;package manager name&gt;@&lt;version&gt;"
    /// }
    /// </code>
    /// </remarks>
    abstract packageManager: string option with get, set
    /// <summary>
    /// The name of the package.
    /// </summary>
    abstract name: string option with get, set
    /// <summary>
    /// Package version, parseable by [<c>node-semver</c>](https://github.com/npm/node-semver).
    /// </summary>
    abstract version: string option with get, set
    /// <summary>
    /// Package description, listed in <c>npm search</c>.
    /// </summary>
    abstract description: string option with get, set
    /// <summary>
    /// Keywords associated with package, listed in <c>npm search</c>.
    /// </summary>
    abstract keywords: string[] option with get, set
    /// <summary>
    /// The URL to the package's homepage.
    /// </summary>
    abstract homepage: obj option with get, set
    /// <summary>
    /// The URL to the package's issue tracker and/or the email address to which issues should be reported.
    /// </summary>
    abstract bugs: U2<string, PackageJsonBugs> option with get, set
    /// <summary>
    /// The license for the package.
    /// </summary>
    abstract license: string option with get, set
    /// <summary>
    /// The licenses for the package.
    /// </summary>
    abstract licenses: PackageJsonLicensesItem[] option with get, set
    abstract author: U2<string, PackageJsonAuthor> option with get, set
    /// <summary>
    /// A list of people who contributed to the package.
    /// </summary>
    abstract contributors: U2<string, PackageJsonAuthor>[] option with get, set
    /// <summary>
    /// A list of people who maintain the package.
    /// </summary>
    abstract maintainers: U2<string, PackageJsonAuthor>[] option with get, set
    /// <summary>
    /// The files included in the package.
    /// </summary>
    abstract files: string[] option with get, set
    /// <summary>
    /// Resolution algorithm for importing ".js" files from the package's scope.
    ///
    /// [Read more.](https://nodejs.org/api/esm.html#esm_package_json_type_field)
    /// </summary>
    abstract ``type``: PackageJsonType option with get, set
    /// <summary>
    /// The module ID that is the primary entry point to the program.
    /// </summary>
    abstract main: string option with get, set
    /// <summary>
    /// Subpath exports to define entry points of the package.
    ///
    /// [Read more.](https://nodejs.org/api/packages.html#subpath-exports)
    /// </summary>
    abstract exports: U3<string, U2<string, PackageJsonExportsItem>[], PackageJsonExportsItem> option with get, set
    /// <summary>
    /// Subpath imports to define internal package import maps that only apply to import specifiers from within the package itself.
    ///
    /// [Read more.](https://nodejs.org/api/packages.html#subpath-imports)
    /// </summary>
    abstract imports: PackageJsonImports option with get, set
    /// <summary>
    /// The executable files that should be installed into the <c>PATH</c>.
    /// </summary>
    abstract bin: U2<string, PackageJsonBin> option with get, set
    /// <summary>
    /// Filenames to put in place for the <c>man</c> program to find.
    /// </summary>
    abstract man: U2<string, string[]> option with get, set
    /// <summary>
    /// Indicates the structure of the package.
    /// </summary>
    abstract directories: PackageJsonDirectories option with get, set
    /// <summary>
    /// Location for the code repository.
    /// </summary>
    abstract repository: U2<string, PackageJsonRepository> option with get, set
    /// <summary>
    /// Script commands that are run at various times in the lifecycle of the package. The key is the lifecycle event, and the value is the command to run at that point.
    /// </summary>
    abstract scripts: PackageJsonScripts option with get, set
    /// <summary>
    /// Is used to set configuration parameters used in package scripts that persist across upgrades.
    /// </summary>
    abstract config: JsonObject option with get, set
    /// <summary>
    /// The dependencies of the package.
    /// </summary>
    abstract dependencies: PackageJsonDependencies option with get, set
    /// <summary>
    /// Additional tooling dependencies that are not required for the package to work. Usually test, build, or documentation tooling.
    /// </summary>
    abstract devDependencies: PackageJsonDependencies option with get, set
    /// <summary>
    /// Dependencies that are skipped if they fail to install.
    /// </summary>
    abstract optionalDependencies: PackageJsonDependencies option with get, set
    /// <summary>
    /// Dependencies that will usually be required by the package user directly or via another dependency.
    /// </summary>
    abstract peerDependencies: PackageJsonDependencies option with get, set
    /// <summary>
    /// Indicate peer dependencies that are optional.
    /// </summary>
    abstract peerDependenciesMeta: PackageJsonPeerDependenciesMeta option with get, set
    /// <summary>
    /// Package names that are bundled when the package is published.
    /// </summary>
    abstract bundledDependencies: string[] option with get, set
    /// <summary>
    /// Alias of <c>bundledDependencies</c>.
    /// </summary>
    abstract bundleDependencies: string[] option with get, set
    /// <summary>
    /// Overrides is used to support selective version overrides using npm, which lets you define custom package versions or ranges inside your dependencies.
    /// </summary>
    abstract overrides: PackageJsonOverrides option with get, set
    /// <summary>
    /// Engines that this package runs on.
    /// </summary>
    abstract engines: PackageJsonEngines option with get, set
    /// <remarks>@deprecated</remarks>
    abstract engineStrict: bool option with get, set
    /// <summary>
    /// Operating systems the module runs on.
    /// </summary>
    abstract os: obj[] option with get, set
    /// <summary>
    /// CPU architectures the module runs on.
    /// </summary>
    abstract cpu: obj[] option with get, set
    /// <summary>
    /// Define the runtime and package manager for developing the current project.
    /// </summary>
    abstract devEngines: PackageJsonDevEngines option with get, set
    /// <summary>
    /// If set to <c>true</c>, a warning will be shown if package is installed locally. Useful if the package is primarily a command-line application that should be installed globally.
    /// </summary>
    /// <remarks>@deprecated</remarks>
    abstract preferGlobal: bool option with get, set
    /// <summary>
    /// If set to <c>true</c>, then npm will refuse to publish it.
    /// </summary>
    abstract ``private``: bool option with get, set
    /// <summary>
    /// A set of config values that will be used at publish-time. It's especially handy to set the tag, registry or access, to ensure that a given package is not tagged with 'latest', published to the global public registry or that a scoped module is private by default.
    /// </summary>
    abstract publishConfig: PackageJsonPublishConfig option with get, set
    /// <summary>
    /// Describes and notifies consumers of a package's monetary support information.
    ///
    /// [Read more.](https://github.com/npm/rfcs/blob/main/implemented/0017-add-funding-support.md)
    /// </summary>
    abstract funding: U2<string, PackageJsonFunding> option with get, set
    /// <summary>
    /// Used to configure [npm workspaces](https://docs.npmjs.com/cli/using-npm/workspaces) / [Yarn workspaces](https://classic.yarnpkg.com/docs/workspaces/).
    ///
    /// Workspaces allow you to manage multiple packages within the same repository in such a way that you only need to run your install command once in order to install all of them in a single pass.
    ///
    /// Please note that the top-level <c>private</c> property of <c>package.json</c> **must** be set to <c>true</c> in order to use workspaces.
    /// </summary>
    abstract workspaces: U2<string[], PackageJsonWorkspaces> option with get, set
    /// <summary>
    /// An ECMAScript module ID that is the primary entry point to the program.
    /// </summary>
    abstract ``module``: string option with get, set
    /// <summary>
    /// A module ID with untranspiled code that is the primary entry point to the program.
    /// </summary>
    abstract esnext: U2<string, PackageJsonEsnext> option with get, set
    /// <summary>
    /// A hint to JavaScript bundlers or component tools when packaging modules for client side use.
    /// </summary>
